// Saju event "후보 Pool" admin list. Filterable by pool stage, nationality,
// preferred role, visa, and recommendation status (the auto-generated tags).
const opsSajuLeadsQuerySchema = z.object({
  poolStage: z.enum(["PROFILE", "VERIFIED", "RECOMMENDABLE"]).optional(),
  recommendStatus: z.enum(["UNVERIFIED", "NEEDS_WORK", "RECOMMENDABLE"]).optional(),
  nationality: z.string().trim().max(80).optional(),
  preferredJobRole: z.string().trim().max(40).optional(),
  visaType: z.string().trim().max(40).optional(),
  q: z.string().trim().max(120).optional(),
  take: z.coerce.number().int().min(1).max(200).optional(),
  skip: z.coerce.number().int().min(0).optional()
});

// GET /ops/resume-pool — 이력서 빌더에서 "기업 추천 후보 등록"(content.poolOptIn)에
// 동의한 학생 이력서 목록. 사주 캠페인(SajuLead)과 별개로, 이력서 퍼널로 유입된
// 후보를 운영자가 검토할 수 있게 한다. content 를 그대로 내려 프론트에서 APLY
// Profile 카드로 렌더한다.
const opsResumePoolQuerySchema = z.object({
  q: z.string().trim().max(80).optional(),
  nationality: z.string().trim().max(60).optional()
});
app.get("/ops/resume-pool", authenticate, requireRoles([MemberRole.OPERATOR]), async (req, res) => {
  const parsed = opsResumePoolQuerySchema.safeParse(req.query);
  if (!parsed.success) return res.status(400).json({ ok: false, message: "invalid query", errors: parsed.error.flatten() });
  try {
    const rows = await prisma.resume.findMany({
      where: { content: { path: ["poolOptIn", "consentedAt"], not: Prisma.JsonNull } },
      orderBy: { updatedAt: "desc" },
      take: 200,
      select: { id: true, title: true, updatedAt: true, content: true, user: { select: { name: true, email: true } } }
    });
    const q = parsed.data.q?.toLowerCase();
    const nat = parsed.data.nationality?.toLowerCase();
    const items = rows
      .map((r) => {
        const content = (r.content ?? {}) as Record<string, unknown>;
        const poolOptIn = content.poolOptIn as { consentedAt?: string } | undefined;
        return {
          resumeId: r.id,
          title: r.title,
          updatedAt: r.updatedAt.toISOString(),
          consentedAt: poolOptIn?.consentedAt ?? null,
          userName: r.user?.name ?? null,
          userEmail: r.user?.email ?? null,
          content
        };
      })
      .filter((it) => {
        if (nat && !String(it.content.nationality ?? "").toLowerCase().includes(nat)) return false;
        if (q) {
          const hay = [it.title, it.userName, it.userEmail, it.content.basicName, it.content.desiredJobRole]
            .map((x) => String(x ?? "").toLowerCase())
            .join(" ");
          if (!hay.includes(q)) return false;
        }
        return true;
      });
    return res.json({ ok: true, items });
  } catch (err) {
    console.error("[ops/resume-pool] failed", err);
    return res.status(500).json({ ok: false, message: "failed to list resume pool" });
  }
});

app.get("/ops/saju/leads", authenticate, requireRoles([MemberRole.OPERATOR]), async (req, res) => {
  const parsed = opsSajuLeadsQuerySchema.safeParse(req.query);
  if (!parsed.success) {
    return res.status(400).json({ ok: false, message: "invalid query", errors: parsed.error.flatten() });
  }
  const f = parsed.data;
  const where: Prisma.SajuLeadWhereInput = {
    ...(f.poolStage ? { poolStage: f.poolStage } : {}),
    ...(f.recommendStatus ? { recommendStatus: f.recommendStatus } : {}),
    ...(f.nationality ? { nationality: { contains: f.nationality, mode: "insensitive" } } : {}),
    ...(f.preferredJobRole ? { preferredJobRole: f.preferredJobRole } : {}),
    ...(f.visaType ? { visaType: f.visaType } : {}),
    ...(f.q
      ? {
          OR: [
            { name: { contains: f.q, mode: "insensitive" } },
            { school: { contains: f.q, mode: "insensitive" } },
            { major: { contains: f.q, mode: "insensitive" } },
            { contact: { contains: f.q, mode: "insensitive" } }
          ]
        }
      : {})
  };
  const take = f.take ?? 50;
  const skip = f.skip ?? 0;
  const [leads, total, stageCounts, predictionsTotal, leadsTotalAll, leadsConverted] = await Promise.all([
    prisma.sajuLead.findMany({
      where,
      orderBy: { createdAt: "desc" },
      take,
      skip,
      include: {
        prediction: {
          select: { shareSlug: true, birthDate: true, gender: true, recommendedRoleNames: true }
        }
      }
    }),
    prisma.sajuLead.count({ where }),
    prisma.sajuLead.groupBy({ by: ["poolStage"], _count: { _all: true } }),
    // Funnel summary — unfiltered totals so the header card stays meaningful
    // regardless of the operator's pool-stage / search filters.
    prisma.sajuPrediction.count(),
    prisma.sajuLead.count(),
    prisma.sajuLead.count({ where: { userId: { not: null } } })
  ]);
  return res.json({
    ok: true,
    total,
    take,
    skip,
    stageCounts: Object.fromEntries(stageCounts.map((s) => [s.poolStage, s._count._all])),
    funnel: {
      predictionsTotal,
      leadsTotal: leadsTotalAll,
      leadsConverted
    },
    leads: leads.map((lead) => ({
      id: lead.id,
      name: lead.name,
      shareSlug: lead.shareSlug,
      nationality: lead.nationality,
      school: lead.school,
      major: lead.major,
      visaType: lead.visaType,
      koreanLevel: lead.koreanLevel,
      englishLevel: lead.englishLevel,
      preferredJobRole: lead.preferredJobRole,
      workType: lead.workType,
      contact: lead.contact,
      contactType: lead.contactType,
      hasResume: lead.hasResume,
      recommendedRoles: lead.recommendedRoles,
      improvements: lead.improvements,
      recommendStatus: lead.recommendStatus,
      poolStage: lead.poolStage,
      tags: lead.tags,
      consentCareer: lead.consentCareer,
      consentRecommend: lead.consentRecommend,
      consentContact: lead.consentContact,
      userId: lead.userId,
      locale: lead.locale,
      createdAt: lead.createdAt.toISOString(),
      birthDate: lead.prediction?.birthDate ? lead.prediction.birthDate.toISOString().slice(0, 10) : null,
      gender: lead.prediction?.gender ?? null
    }))
  });
});

// GET /ops/hanpass/survey — 한패스 × Aply 설문 이벤트 응답 관리. 선착순 첨삭
// 10명 선별을 위해 createdAt 오름차순(먼저 응답한 순)으로 정렬해 상단이 1순위.
const opsHanpassSurveyQuerySchema = z.object({
  wantsConsulting: z.enum(["yes", "info_only", "unsure"]).optional(),
  q: z.string().trim().max(120).optional(),
  take: z.coerce.number().int().min(1).max(200).optional(),
  skip: z.coerce.number().int().min(0).optional()
});

app.get("/ops/hanpass/survey", authenticate, requireRoles([MemberRole.OPERATOR]), async (req, res) => {
  const parsed = opsHanpassSurveyQuerySchema.safeParse(req.query);
  if (!parsed.success) {
    return res.status(400).json({ ok: false, message: "invalid query", errors: parsed.error.flatten() });
  }
  const f = parsed.data;
  const where: Prisma.HanpassSurveyResponseWhereInput = {
    ...(f.wantsConsulting ? { wantsConsulting: f.wantsConsulting } : {}),
    ...(f.q
      ? {
          OR: [
            { name: { contains: f.q, mode: "insensitive" } },
            { phone: { contains: f.q, mode: "insensitive" } },
            { email: { contains: f.q, mode: "insensitive" } }
          ]
        }
      : {})
  };
  const take = f.take ?? 50;
  const skip = f.skip ?? 0;
  const [responses, total, wantsCounts, grandTotal] = await Promise.all([
    prisma.hanpassSurveyResponse.findMany({ where, orderBy: { createdAt: "asc" }, take, skip }),
    prisma.hanpassSurveyResponse.count({ where }),
    // 첨삭 신청 여부별 카운트 — 필터와 무관한 전체 기준 (헤더 요약용).
    prisma.hanpassSurveyResponse.groupBy({ by: ["wantsConsulting"], _count: { _all: true } }),
    prisma.hanpassSurveyResponse.count()
  ]);
  const wantsCountMap = Object.fromEntries(wantsCounts.map((w) => [w.wantsConsulting, w._count._all]));
  return res.json({
    ok: true,
    total,
    take,
    skip,
    summary: {
      total: grandTotal,
      applicants: wantsCountMap.yes ?? 0,
      infoOnly: wantsCountMap.info_only ?? 0,
      unsure: wantsCountMap.unsure ?? 0
    },
    responses: responses.map((r, idx) => ({
      // skip 기준 선착순 순번 (1부터). 첨삭 필터 적용 시 신청자 내 순번.
      rank: skip + idx + 1,
      id: r.id,
      name: r.name,
      phone: r.phone,
      email: r.email,
      jobIntent: r.jobIntent,
      availableFrom: r.availableFrom,
      jobFields: r.jobFields,
      jobFieldOther: r.jobFieldOther,
      visaType: r.visaType,
      wantsConsulting: r.wantsConsulting,
      consultLanguages: r.consultLanguages,
      privacyConsent: r.privacyConsent,
      locale: r.locale,
      createdAt: r.createdAt.toISOString(),
      updatedAt: r.updatedAt.toISOString()
    }))
  });
});

// GET /ops/visa/leads — visa funnel 의 익명 lead 풀 관리. saju 와 동일한 모양
