// ---------------------------------------------------------------------------
// Raw-pool endpoints — funnel form 을 채우지 않고 "결과만 본 사람"의 익명
// 데이터까지 ops 콘솔에서 직접 조회할 수 있게 한다. /ops/visa/leads 와
// /ops/saju/leads 가 보여주는 "전환된 lead" 의 상위 단계 pool.
// ---------------------------------------------------------------------------

const opsVisaChecksQuerySchema = z.object({
  nationality: z.string().trim().max(80).optional(),
  currentVisa: z.string().trim().max(20).optional(),
  educationLevel: z.enum(["HIGH_SCHOOL", "BACHELOR", "MASTER", "PHD"]).optional(),
  koreanLevel: z.enum(["NONE", "BEGINNER", "INTERMEDIATE", "ADVANCED", "NATIVE"]).optional(),
  graduationStatus: z.enum(["not_applicable", "completed", "within_6mo", "within_1y", "later"]).optional(),
  inKorea: z.coerce.boolean().optional(),
  hasJobOffer: z.coerce.boolean().optional(),
  claimed: z.enum(["any", "claimed", "unclaimed"]).optional(),
  q: z.string().trim().max(120).optional(),
  take: z.coerce.number().int().min(1).max(200).optional(),
  skip: z.coerce.number().int().min(0).optional()
});

app.get("/ops/visa/checks", authenticate, requireRoles([MemberRole.OPERATOR]), async (req, res) => {
  const parsed = opsVisaChecksQuerySchema.safeParse(req.query);
  if (!parsed.success) {
    return res.status(400).json({ ok: false, message: "invalid query", errors: parsed.error.flatten() });
  }
  const f = parsed.data;
  const where: Prisma.VisaCheckResultWhereInput = {
    ...(f.nationality ? { nationality: { contains: f.nationality, mode: "insensitive" } } : {}),
    ...(f.currentVisa ? { currentVisa: f.currentVisa } : {}),
    ...(f.educationLevel ? { educationLevel: f.educationLevel } : {}),
    ...(f.koreanLevel ? { koreanLevel: f.koreanLevel } : {}),
    ...(f.graduationStatus ? { graduationStatus: f.graduationStatus } : {}),
    ...(f.inKorea !== undefined ? { inKorea: f.inKorea } : {}),
    ...(f.hasJobOffer !== undefined ? { hasJobOffer: f.hasJobOffer } : {}),
    ...(f.claimed === "claimed" ? { userId: { not: null } } : {}),
    ...(f.claimed === "unclaimed" ? { userId: null } : {}),
    ...(f.q
      ? {
          OR: [
            { name: { contains: f.q, mode: "insensitive" } },
            { targetRole: { contains: f.q, mode: "insensitive" } },
            { nationality: { contains: f.q, mode: "insensitive" } }
          ]
        }
      : {})
  };
  const take = f.take ?? 50;
  const skip = f.skip ?? 0;
  const [checks, total, claimedCount] = await Promise.all([
    prisma.visaCheckResult.findMany({
      where,
      orderBy: { createdAt: "desc" },
      take,
      skip,
      select: {
        id: true,
        name: true,
        nationality: true,
        currentVisa: true,
        educationLevel: true,
        majorCategory: true,
        koreanLevel: true,
        workYears: true,
        targetRole: true,
        inKorea: true,
        hasJobOffer: true,
        graduationStatus: true,
        recommendedPositionIds: true,
        shareSlug: true,
        userId: true,
        locale: true,
        createdAt: true,
        claimedAt: true,
        leads: { select: { id: true } }
      }
    }),
    prisma.visaCheckResult.count({ where }),
    prisma.visaCheckResult.count({ where: { userId: { not: null } } })
  ]);
  return res.json({
    ok: true,
    total,
    take,
    skip,
    claimedTotal: claimedCount,
    checks: checks.map((c) => ({
      id: c.id,
      name: c.name,
      nationality: c.nationality,
      currentVisa: c.currentVisa,
      educationLevel: c.educationLevel,
      majorCategory: c.majorCategory,
      koreanLevel: c.koreanLevel,
      workYears: c.workYears,
      targetRole: c.targetRole,
      inKorea: c.inKorea,
      hasJobOffer: c.hasJobOffer,
      graduationStatus: c.graduationStatus,
      recommendedPositionCount: c.recommendedPositionIds.length,
      shareSlug: c.shareSlug,
      userId: c.userId,
      locale: c.locale,
      createdAt: c.createdAt.toISOString(),
      claimedAt: c.claimedAt?.toISOString() ?? null,
      hasLead: c.leads.length > 0
    }))
  });
});

const opsSajuPredictionsQuerySchema = z.object({
  gender: z.enum(["male", "female"]).optional(),
  claimed: z.enum(["any", "claimed", "unclaimed"]).optional(),
  q: z.string().trim().max(120).optional(),
  take: z.coerce.number().int().min(1).max(200).optional(),
  skip: z.coerce.number().int().min(0).optional()
});

app.get("/ops/saju/predictions", authenticate, requireRoles([MemberRole.OPERATOR]), async (req, res) => {
  const parsed = opsSajuPredictionsQuerySchema.safeParse(req.query);
  if (!parsed.success) {
    return res.status(400).json({ ok: false, message: "invalid query", errors: parsed.error.flatten() });
  }
  const f = parsed.data;
  const where: Prisma.SajuPredictionWhereInput = {
    ...(f.gender ? { gender: f.gender } : {}),
    ...(f.claimed === "claimed" ? { userId: { not: null } } : {}),
    ...(f.claimed === "unclaimed" ? { userId: null } : {}),
    ...(f.q ? { name: { contains: f.q, mode: "insensitive" } } : {})
  };
  const take = f.take ?? 50;
  const skip = f.skip ?? 0;
  const [predictions, total, claimedCount] = await Promise.all([
    prisma.sajuPrediction.findMany({
      where,
      orderBy: { createdAt: "desc" },
      take,
      skip,
      select: {
        id: true,
        name: true,
        gender: true,
        birthDate: true,
        birthTime: true,
        calendarType: true,
        recommendedRoleNames: true,
        recommendedPositionIds: true,
        shareSlug: true,
        userId: true,
        locale: true,
        createdAt: true,
        claimedAt: true,
        leads: { select: { id: true } }
      }
    }),
    prisma.sajuPrediction.count({ where }),
    prisma.sajuPrediction.count({ where: { userId: { not: null } } })
  ]);
  return res.json({
    ok: true,
    total,
    take,
    skip,
    claimedTotal: claimedCount,
    predictions: predictions.map((p) => ({
      id: p.id,
      name: p.name,
      gender: p.gender,
      birthDate: p.birthDate.toISOString().slice(0, 10),
      birthTime: p.birthTime,
      calendarType: p.calendarType,
      recommendedRoleNames: p.recommendedRoleNames,
      recommendedPositionCount: p.recommendedPositionIds.length,
      shareSlug: p.shareSlug,
      userId: p.userId,
      locale: p.locale,
      createdAt: p.createdAt.toISOString(),
      claimedAt: p.claimedAt?.toISOString() ?? null,
      hasLead: p.leads.length > 0
    }))
  });
});

// ---------------------------------------------------------------------------
// SGC × Aply 일경험 프로그램 — 운영자 콘솔용. 지원 풀 조회 + 단계 변경 +
// 운영 메모. 각 row 는 사용자 + 이력서 메타가 join 되어 ops 화면에서 즉시
// 면접/검토를 돌릴 수 있게 한다.
// ---------------------------------------------------------------------------

const opsSgcApplicationsQuerySchema = z.object({
  status: z.enum(["SUBMITTED", "INTERVIEW", "ACCEPTED", "REJECTED", "WITHDRAWN"]).optional(),
  visaType: z.enum(["D-2", "D-10", "OTHER"]).optional(),
  desiredJob: z.enum(["MARKETING", "SALES", "TRANSLATION", "DEV", "OTHER"]).optional(),
  q: z.string().trim().max(120).optional(),
  take: z.coerce.number().int().min(1).max(200).optional(),
  skip: z.coerce.number().int().min(0).optional()
});

app.get("/ops/sgc/applications", authenticate, requireRoles([MemberRole.OPERATOR]), async (req, res) => {
  const parsed = opsSgcApplicationsQuerySchema.safeParse(req.query);
  if (!parsed.success) {
    return res.status(400).json({ ok: false, message: "invalid query", errors: parsed.error.flatten() });
  }
  const f = parsed.data;
  const where: Prisma.SgcApplicationWhereInput = {
    ...(f.status ? { status: f.status } : {}),
    ...(f.visaType ? { visaType: f.visaType } : {}),
    ...(f.desiredJob ? { desiredJob: f.desiredJob } : {}),
    ...(f.q
      ? {
          OR: [
            { user: { name: { contains: f.q, mode: "insensitive" } } },
            { user: { realName: { contains: f.q, mode: "insensitive" } } },
            { user: { email: { contains: f.q, mode: "insensitive" } } }
          ]
        }
      : {})
  };
  const take = f.take ?? 50;
  const skip = f.skip ?? 0;
  const [applications, total, statusCounts, totalAll] = await Promise.all([
    prisma.sgcApplication.findMany({
      where,
      orderBy: { createdAt: "desc" },
      take,
      skip,
      include: {
        user: {
          select: { id: true, email: true, name: true, realName: true, phoneNumber: true, nationality: true }
        },
        resume: {
          select: { id: true, title: true, shareSlug: true, updatedAt: true }
        }
      }
    }),
    prisma.sgcApplication.count({ where }),
    prisma.sgcApplication.groupBy({ by: ["status"], _count: { _all: true } }),
    prisma.sgcApplication.count()
  ]);
  return res.json({
    ok: true,
    total,
    take,
    skip,
    totalAll,
    statusCounts: Object.fromEntries(statusCounts.map((s) => [s.status, s._count._all])),
    applications: applications.map((a) => ({
      id: a.id,
      status: a.status,
      visaType: a.visaType,
      visaOther: a.visaOther,
      healthNote: a.healthNote,
      desiredJob: a.desiredJob,
      desiredJobOther: a.desiredJobOther,
      motivation: a.motivation,
      marketingOptIn: a.marketingOptIn,
      locale: a.locale,
      adminMemo: a.adminMemo,
      createdAt: a.createdAt.toISOString(),
      updatedAt: a.updatedAt.toISOString(),
      user: a.user
        ? {
            id: a.user.id,
            email: a.user.email,
            name: a.user.name ?? a.user.realName,
            phoneNumber: a.user.phoneNumber,
            nationality: a.user.nationality
          }
        : null,
      resume: a.resume
        ? {
            id: a.resume.id,
            title: a.resume.title,
            shareSlug: a.resume.shareSlug,
            updatedAt: a.resume.updatedAt.toISOString()
          }
        : null
    }))
  });
});

// PATCH /ops/sgc/applications/:id — 단계 변경 + 운영 메모. 운영자가 면접/
// 합격/거절 처리 시 사용. 사용자가 "WITHDRAWN" 으로 본인 지원을 취소하는
// flow 는 별도 엔드포인트가 더 깔끔 (현재 범위 밖).
const opsSgcApplicationUpdateSchema = z.object({
  status: z.enum(["SUBMITTED", "INTERVIEW", "ACCEPTED", "REJECTED", "WITHDRAWN"]).optional(),
  adminMemo: z.string().trim().max(4000).nullable().optional()
});

app.patch("/ops/sgc/applications/:id", authenticate, requireRoles([MemberRole.OPERATOR]), async (req, res) => {
  const id = typeof req.params.id === "string" ? req.params.id : "";
  if (!id) return res.status(400).json({ ok: false, message: "missing id" });
  const parsed = opsSgcApplicationUpdateSchema.safeParse(req.body);
  if (!parsed.success) {
    return res.status(400).json({ ok: false, message: "invalid request", errors: parsed.error.flatten() });
  }
  const data: Prisma.SgcApplicationUpdateInput = {};
  if (parsed.data.status !== undefined) data.status = parsed.data.status;
  if (parsed.data.adminMemo !== undefined) data.adminMemo = parsed.data.adminMemo;
  try {
    // 이전 status 가 무엇인지 알아야 "변경 됐을 때만 알림" 분기가 가능. 그래서
    // update 전에 한 번 select.
    const before = await prisma.sgcApplication.findUnique({
      where: { id },
      select: { userId: true, status: true }
    });
    if (!before) return res.status(404).json({ ok: false, message: "not found" });

    const updated = await prisma.sgcApplication.update({
      where: { id },
      data,
      select: { id: true, status: true, adminMemo: true, updatedAt: true }
    });

    // status 가 실제로 바뀌었을 때만 사용자 알림. 변경 없는 메모만 저장한
    // 경우엔 알림 없음.
    if (parsed.data.status && parsed.data.status !== before.status) {
      const NOTIFY: Record<
        "SUBMITTED" | "INTERVIEW" | "ACCEPTED" | "REJECTED" | "WITHDRAWN",
        { title: string; message: string } | null
      > = {
        SUBMITTED: {
          title: "SGC × Aply 일경험 — 접수 상태로 복귀",
          message: "지원이 다시 접수 단계로 표시됐어요. 운영팀이 재검토 중입니다."
        },
        INTERVIEW: {
          title: "SGC × Aply 일경험 — 면접 단계",
          message: "면접 단계로 이동했어요. 곧 운영팀이 면접 일정을 안내드릴 예정입니다."
        },
        ACCEPTED: {
          title: "🎉 SGC × Aply 일경험 — 합격 안내",
          message: "축하해요! 합격하셨습니다. 곧 운영팀이 다음 단계를 안내드릴게요."
        },
        REJECTED: {
          title: "SGC × Aply 일경험 — 결과 안내",
          message: "이번 모집에서는 함께하지 못하게 됐어요. 관심 가져주셔서 진심으로 감사합니다."
        },
        // 운영자가 WITHDRAWN 으로 바꿀 일은 드물지만, 일관성을 위해 메시지 정의.
        WITHDRAWN: {
          title: "SGC × Aply 일경험 — 지원 취소",
          message: "지원이 취소 처리됐어요. 문의는 운영팀으로 부탁드립니다."
        }
      };
      const notice = NOTIFY[parsed.data.status];
      if (notice) {
        void createNotification({
          userId: before.userId,
          type: `SGC_APPLICATION_STATUS_${parsed.data.status}`,
          title: notice.title,
          message: notice.message,
          linkPath: "/profile?tab=sgc"
        });
      }
    }

    return res.json({ ok: true, application: updated });
  } catch (error) {
    // 존재 여부는 위에서 이미 404 로 걸렀으므로, 여기로 오는 건 실제 DB/제약
    // 오류다. 404 로 마스킹하지 않고 로깅 + 500 으로 명확히 반환 (DELETE 와 동일).
    console.error("[ops/sgc/applications][patch][failed]", {
      id,
      message: error instanceof Error ? error.message : String(error)
    });
    return res.status(500).json({ ok: false, message: "failed to update application" });
  }
});

// DELETE /ops/sgc/applications/:id — 운영자가 지원 자체를 삭제. 주된 용도는
// 테스트(같은 계정으로 다시 신청해보기) 와 명백한 오등록 정리. 사용자가
// 자발적으로 취소하는 케이스는 status=WITHDRAWN PATCH 가 맞고, 이 엔드포인트는
// 행 자체를 지운다. @@unique([userId]) 라 이 행이 살아 있으면 동일 유저의
// 재신청이 P2002 로 막히는데, 삭제하면 다시 깨끗하게 신청 가능.
app.delete("/ops/sgc/applications/:id", authenticate, requireRoles([MemberRole.OPERATOR]), async (req, res) => {
  const id = typeof req.params.id === "string" ? req.params.id : "";
  if (!id) return res.status(400).json({ ok: false, message: "missing id" });
  try {
    // 존재 여부 먼저 확인 — 없으면 404 로 명확히 반환 (delete 가 P2025 던지면
    // status 만으로 구분하기 애매해서).
    const found = await prisma.sgcApplication.findUnique({
      where: { id },
      select: { id: true, userId: true }
    });
    if (!found) return res.status(404).json({ ok: false, message: "not found" });

    await prisma.sgcApplication.delete({ where: { id } });

    // 사용자 알림은 굳이 보내지 않는다 — 운영자가 테스트/정리 목적으로 삭제하는
    // 경로라 사용자 입장에서 별도 안내가 오히려 혼란. 디스코드 운영 채널엔
    // 향후 필요하면 별도 hook 으로 알릴 수 있음.

    return res.json({ ok: true, id: found.id });
  } catch (error) {
    console.error("[ops/sgc/applications][delete][failed]", {
      id,
      message: error instanceof Error ? error.message : String(error)
    });
    return res.status(500).json({ ok: false, message: "failed to delete application" });
  }
});

const companyConsultationCreateSchema = z.object({
  companyName: z.string().trim().min(1).max(120),
  contactName: z.string().trim().min(1).max(80),
  email: z.string().trim().email().max(320),
  phone: z.string().trim().max(40).optional(),
  message: z.string().trim().min(1).max(4000),
  locale: z.enum(["ko", "en"]).optional(),
  source: z.string().trim().max(80).optional()
});

const hanpassSurveyCreateSchema = z.object({
  name: z.string().trim().min(1).max(80),
  phone: z.string().trim().min(1).max(40),
  email: z.string().trim().email().max(320),
  jobIntent: z.enum(["active_seeking", "open_to_offers", "not_seeking", "unsure"]),
  availableFrom: z.enum(["immediately", "within_1m", "within_3m", "undecided", "not_available"]),
  jobFields: z
    .array(
      z.enum([
        "manufacturing",
        "logistics",
        "service",
        "office",
        "translation",
        "it",
        "design_marketing",
        "research",
        "other"
      ])
    )
    .min(1, "희망 분야를 한 가지 이상 선택해 주세요")
    .max(9),
  jobFieldOther: z.string().trim().max(120).optional(),
  visaType: z.enum(["D-2", "D-4", "D-10", "E-7", "F-2", "F-4", "F-5", "F-6", "other", "unsure"]),
  wantsConsulting: z.enum(["yes", "info_only", "unsure"]),
  consultLanguages: z.array(z.enum(["ko", "en"])).min(1, "상담 가능한 언어를 선택해 주세요").max(2),
  privacyConsent: z.literal(true, {
    errorMap: () => ({ message: "개인정보 활용에 동의해야 설문을 제출할 수 있습니다" })
  }),
  locale: z.enum(["ko", "en"]).optional(),
  source: z.string().trim().max(80).optional()
});

app.post("/company-consultations", async (req, res) => {
  const parsed = companyConsultationCreateSchema.safeParse(req.body);
  if (!parsed.success) {
    return res.status(400).json({
      ok: false,
      message: "Invalid request body",
      issues: parsed.error.flatten()
    });
  }

  const payload = parsed.data;
  const created = await prisma.companyConsultationInquiry.create({
    data: {
      companyName: payload.companyName,
      contactName: payload.contactName,
      email: payload.email,
      phone: payload.phone || null,
      message: payload.message,
      locale: payload.locale ?? "ko",
      source: payload.source ?? "platform-web"
    }
  });

  await sendCompanyConsultationDiscordNotification({
    id: created.id,
    companyName: created.companyName,
    contactName: created.contactName,
    email: created.email,
    phone: created.phone,
    message: created.message,
    locale: created.locale,
    source: created.source,
    createdAt: created.createdAt
  });

  return res.status(201).json({
    ok: true,
    message: "Consultation inquiry created",
    item: {
      id: created.id,
      createdAt: created.createdAt
    }
  });
});

app.post(
  "/events/hanpass/survey",
  rateLimit({ windowMs: 60_000, max: 8, keyPrefix: "hanpass-survey", message: "잠시 후 다시 시도해 주세요." }),
  async (req, res) => {
    const parsed = hanpassSurveyCreateSchema.safeParse(req.body);
    if (!parsed.success) {
      return res.status(400).json({
        ok: false,
        message: "Invalid request body",
        issues: parsed.error.flatten()
      });
    }

    const payload = parsed.data;

    if (payload.jobFields.includes("other") && !(payload.jobFieldOther && payload.jobFieldOther.trim())) {
      return res
        .status(400)
        .json({ ok: false, message: "기타 분야를 선택한 경우 내용을 입력해 주세요" });
    }

    const ipRaw =
      (req.headers["x-forwarded-for"] as string | undefined)?.split(",")[0]?.trim() ||
      req.socket.remoteAddress ||
      "";
    const ipHash = ipRaw
      ? createHash("sha256").update(`${ipRaw}|hanpass-survey`).digest("hex").slice(0, 32)
      : null;

    // 소프트 중복 처리: 같은 전화번호(숫자만 정규화)면 기존 응답을 갱신.
    // createdAt(최초 제출 시각)은 유지하여 선착순 공정성을 보존하고, 운영팀
    // 명단에 한 사람당 1행만 남도록 한다. 하드 차단이 아니라 답변 수정 허용.
    const normalizedPhone = payload.phone.replace(/[^0-9]/g, "") || payload.phone.trim();

    const data = {
      name: payload.name,
      phone: normalizedPhone,
      email: payload.email,
      jobIntent: payload.jobIntent,
      availableFrom: payload.availableFrom,
      jobFields: payload.jobFields,
      jobFieldOther: payload.jobFieldOther?.trim() || null,
      visaType: payload.visaType,
      wantsConsulting: payload.wantsConsulting,
      consultLanguages: payload.consultLanguages,
      privacyConsent: payload.privacyConsent,
      locale: payload.locale ?? "ko",
      source: payload.source ?? "hanpass",
      ipHash
    };

    const existing = await prisma.hanpassSurveyResponse.findFirst({
      where: { phone: normalizedPhone },
      orderBy: { createdAt: "asc" }
    });

    const isUpdate = Boolean(existing);
    const created = existing
      ? await prisma.hanpassSurveyResponse.update({ where: { id: existing.id }, data })
      : await prisma.hanpassSurveyResponse.create({ data });

    await sendHanpassSurveyDiscordNotification({
      id: created.id,
      name: created.name,
      phone: created.phone,
      email: created.email,
      jobIntent: created.jobIntent,
      availableFrom: created.availableFrom,
      jobFields: created.jobFields,
      jobFieldOther: created.jobFieldOther,
      visaType: created.visaType,
      wantsConsulting: created.wantsConsulting,
      consultLanguages: created.consultLanguages,
      privacyConsent: created.privacyConsent,
      locale: created.locale,
      source: created.source,
      createdAt: created.createdAt,
      isUpdate
    });

    return res.status(isUpdate ? 200 : 201).json({
      ok: true,
      message: isUpdate ? "Hanpass survey response updated" : "Hanpass survey response created",
      item: {
        id: created.id,
        wantsConsulting: created.wantsConsulting,
        createdAt: created.createdAt,
        updated: isUpdate
      }
    });
  }
);

app.post("/internal/company-consultations/discord-test", async (req, res) => {
  if (!companyConsultationDiscordTestToken) {
    return res.status(503).json({
      ok: false,
      message: "Test token is not configured (set COMPANY_CONSULTATION_DISCORD_TEST_TOKEN)"
    });
  }
  if (!hasValidCompanyConsultationDiscordTestToken(req)) {
    return res.status(401).json({
      ok: false,
      message: "Unauthorized"
    });
  }
  if (!discordCompanyConsultationWebhookUrl) {
    return res.status(503).json({
      ok: false,
      message: "Discord webhook is not configured (set DISCORD_COMPANY_CONSULTATION_WEBHOOK_URL)"
    });
  }

  const now = new Date();
  await sendCompanyConsultationDiscordNotification({
    id: `test-${now.getTime()}`,
    companyName: "Webhook Healthcheck",
    contactName: "System",
    email: "noreply@flip-ers.com",
    phone: null,
    message: "This is a test notification from /internal/company-consultations/discord-test",
    locale: "ko",
    source: "internal-test",
    createdAt: now
  });

  return res.status(200).json({
    ok: true,
    message: "Discord test notification attempted. Check API logs for delivery errors."
  });
});

app.get("/members/meta", (_req, res) => {
  res.json({
    ok: true,
    roles: Object.values(MemberRole),
    partnerTypes: Object.values(PartnerType),
    partnerOrgUserRoles: Object.values(PartnerOrgUserRole),
    partnerCompanySizes: partnerCompanySizeEnum.options,
    partnerIndustries: Object.values(PartnerIndustry),
    candidateVisaTypes: Object.values(CandidateVisaType)
  });
});

app.get("/positions/meta", async (_req, res) => {
  const [partnerIndustries, partnerCompanySizes, rolesRaw, workTypesRaw, eligibleVisasRaw] = await Promise.all([
    prisma.partnerOrganization.findMany({
      where: { positions: { some: {} } },
      distinct: ["industry"],
      select: { industry: true }
    }),
    prisma.partnerOrganization.findMany({
      where: {
        companySize: { not: null },
        positions: { some: {} }
      },
      distinct: ["companySize"],
      select: { companySize: true }
    }),
    prisma.position.findMany({
      where: {
        preferredJobRole: {
          not: null
        }
      },
      select: {
        preferredJobRole: true
      }
    }),
    prisma.position.findMany({
      where: { workType: { not: null } },
      distinct: ["workType"],
      select: { workType: true }
    }),
    prisma.position.findMany({
      where: { eligibleVisas: { isEmpty: false } },
      select: { eligibleVisas: true }
    })
  ]);

  const jobRoles = Array.from(
    new Set(
      rolesRaw
        .map((item) => item.preferredJobRole?.trim() ?? "")
        .filter((value) => value.length > 0)
    )
  ).sort((a, b) => a.localeCompare(b, "ko-KR"));

  res.json({
    ok: true,
    partnerIndustries: partnerIndustries.map((item) => item.industry),
    partnerCompanySizes: partnerCompanySizes
      .map((item) => item.companySize)
      .filter((value): value is z.infer<typeof partnerCompanySizeEnum> => Boolean(value)),
    jobRoles,
    candidateVisaTypes: Array.from(
      new Set(
        eligibleVisasRaw.flatMap((item) => item.eligibleVisas).map((value) => value.trim()).filter((value) => value.length > 0)
      )
    ),
    workTypes: Array.from(
      new Set(
        workTypesRaw
          .map((item) => item.workType?.trim() ?? "")
          .filter((value) => value.length > 0)
      )
    )
  });
});

