// 학생 주차 게이팅용 — 본인 기수의 주차 오픈 일정 + 서버 현재시각.
// forceOpen 이거나 opensAt<=now 면 그 주차는 날짜상 열림(미설정이면 프론트가 진행 기반으로 폴백).
app.get("/career-launch/week-schedule", authenticate, requireCareerEnrollment, async (req, res) => {
  try {
    const enrollment = await prisma.careerEnrollment.findFirst({
      where: { studentUserId: req.auth!.userId },
      orderBy: { createdAt: "desc" },
      select: { cohortId: true }
    });
    let weekSchedule = [1, 2, 3, 4].map((w) => ({ week: w, opensAt: null as Date | null, forceOpen: false }));
    if (enrollment?.cohortId) {
      const weeks = await prisma.careerCohortWeek.findMany({ where: { cohortId: enrollment.cohortId } });
      const m = new Map(weeks.map((w) => [w.week, w] as const));
      weekSchedule = [1, 2, 3, 4].map((w) => ({ week: w, opensAt: m.get(w)?.opensAt ?? null, forceOpen: m.get(w)?.forceOpen ?? false }));
    }
    return res.json({ ok: true, weekSchedule, serverNow: new Date().toISOString() });
  } catch (error) {
    return res.status(500).json({ ok: false, message: getErrorMessage(error) });
  }
});

// PATCH /career-launch/progress — 제공된 키만 얕게 병합해 저장(부분 갱신).
const progressPatchSchema = z.record(z.string(), z.unknown());
// 완주 시 수료증 자동 발급 — 모의면접 3라운드 + 이력서 + 자소서 완성이면 수료증 생성(중복 방지) + 알림.
async function maybeAutoIssueCareerCertificate(userId: string, state: Record<string, unknown>) {
  try {
    const interview = (state.interview && typeof state.interview === "object" ? state.interview : {}) as { practiced?: unknown };
    const practiced = Array.isArray(interview.practiced) ? (interview.practiced as string[]) : [];
    if (practiced.length < 3) return;

    const [resume, cover] = await Promise.all([
      prisma.careerResumeData.findUnique({ where: { studentUserId: userId }, select: { content: true } }),
      prisma.careerCoverLetterData.findUnique({ where: { studentUserId: userId }, select: { content: true } })
    ]);
    const rc = (resume?.content ?? {}) as Record<string, unknown>;
    const cc = (cover?.content ?? {}) as Record<string, unknown>;
    const hasResume =
      (Array.isArray(rc.educations) && rc.educations.length > 0) ||
      (Array.isArray(rc.experiences) && rc.experiences.length > 0) ||
      (Array.isArray(rc.skills) && rc.skills.length > 0) ||
      Boolean((rc.basic as { name?: string } | undefined)?.name);
    const coverItems = Array.isArray(cc.items) ? (cc.items as { answer?: string }[]).filter((x) => (x.answer ?? "").trim()).length : 0;
    if (!hasResume || coverItems === 0) return;

    const enrollment = await prisma.careerEnrollment.findFirst({ where: { studentUserId: userId }, orderBy: { createdAt: "desc" }, select: { cohortId: true } });
    if (!enrollment?.cohortId) return;
    const cohortId = enrollment.cohortId;

    const existing = await prisma.careerLaunchCertificate.findUnique({ where: { cohortId_studentUserId: { cohortId, studentUserId: userId } } });
    if (existing) return;

    const seq = (await prisma.careerLaunchCertificate.count({ where: { cohortId } })) + 1;
    const certificateNo = `APLY-CL-${cohortId.slice(0, 8).toUpperCase()}-${String(seq).padStart(3, "0")}`;
    await prisma.careerLaunchCertificate.create({ data: { cohortId, studentUserId: userId, certificateNo, issuedByUserId: null } }).catch(() => {});

    void createNotification({ userId, type: "CAREER_CERTIFICATE_ISSUED", title: "Career Launch 수료증이 발급되었어요", message: certificateNo, linkPath: "/career-launch/dashboard" });
    const u = await prisma.user.findUnique({ where: { id: userId }, select: { email: true } });
    if (u?.email) {
      void sendNotificationEmail({
        toUser: { id: userId, email: u.email },
        subject: "[Aply] Career Launch 수료증 발급",
        previewText: "프로그램을 완주하여 수료증이 발급되었어요",
        title: "수료증 발급",
        headline: "Career Launch를 완주하셨어요!",
        bodyText: `축하합니다! 4주 프로그램을 완주하여 수료증(${certificateNo})이 발급되었습니다. 취업 성과 설문에도 참여해 주세요.`,
        ctaLabel: "수료증·설문 보기",
        ctaPath: "/career-launch/survey",
        footerNote: "본 메일은 Career Launch 프로그램 완주에 따라 발송되는 알림입니다.",
        logKey: "career_certificate_email"
      });
    }
  } catch (error) {
    console.error("auto_certificate_failed", { error: getErrorMessage(error) });
  }
}

app.patch("/career-launch/progress", authenticate, requireCareerEnrollment, async (req, res) => {
  const parsed = progressPatchSchema.safeParse(req.body);
  if (!parsed.success) return res.status(400).json({ ok: false, message: "invalid request" });
  try {
    const existing = await prisma.careerLaunchProgress.findUnique({ where: { studentUserId: req.auth!.userId } });
    const prev = (existing?.state && typeof existing.state === "object" ? existing.state : {}) as Record<string, unknown>;
    const merged = { ...prev, ...parsed.data };

    // 진단 이력 — 성과 리포트의 '사전 → 사후 향상도'는 여기서만 만들어진다.
    // 클라이언트가 값을 지어내지 못하도록 서버가 직접 기록한다:
    //   diagnosisInitial : 최초 1회만 기록(이후 덮어쓰지 않음)
    //   diagnosisFinal   : 수료 재진단(body.finalDiagnosis === true)일 때만 기록
    const incoming = (parsed.data as Record<string, unknown>).diagnosis;
    if (incoming && typeof incoming === "object") {
      const stamped = { ...(incoming as Record<string, unknown>), at: new Date().toISOString() };
      if (!prev.diagnosisInitial) {
        // 이 기능 이전에 이미 진단한 학생은 diagnosisInitial 이 없다.
        // 그때 들어오는 진단(=수료 재진단일 수도 있다)을 사전 진단으로 기록하면
        // 기존 점수가 baseline 에서 사라져 향상도가 0이 된다.
        // 따라서 기존 진단이 있으면 그것을 사전 진단으로 승격하고,
        // 아예 처음 진단하는 학생만 이번 값을 사전 진단으로 삼는다.
        merged.diagnosisInitial = prev.diagnosis ?? stamped;
      }
      if ((req.body as Record<string, unknown>).finalDiagnosis === true) merged.diagnosisFinal = stamped;
    }
    delete (merged as Record<string, unknown>).finalDiagnosis; // 플래그는 상태에 남기지 않는다
    await prisma.careerLaunchProgress.upsert({
      where: { studentUserId: req.auth!.userId },
      create: { studentUserId: req.auth!.userId, state: merged as object },
      update: { state: merged as object }
    });
    // 완주 조건 충족 시 수료증 자동 발급(중복은 내부에서 방지).
    void maybeAutoIssueCareerCertificate(req.auth!.userId, merged as Record<string, unknown>);
    return res.json({ ok: true, state: merged });
  } catch (error) {
    return res.status(500).json({ ok: false, message: getErrorMessage(error) });
  }
});

// ── 취업 성과 설문(수료생 자기 보고) ──
// GET: 내 수료증 발급 여부 + 이미 제출한 성과. POST: 취업 상태 자기 보고(자기 기록으로 upsert).
app.get("/career-launch/me/employment-status", authenticate, requireCareerEnrollment, async (req, res) => {
  try {
    const userId = req.auth!.userId;
    const enrollment = await prisma.careerEnrollment.findFirst({ where: { studentUserId: userId }, orderBy: { createdAt: "desc" }, select: { cohortId: true } });
    const cohortId = enrollment?.cohortId ?? null;
    const [cert, outcome] = await Promise.all([
      cohortId ? prisma.careerLaunchCertificate.findUnique({ where: { cohortId_studentUserId: { cohortId, studentUserId: userId } }, select: { certificateNo: true, issuedAt: true } }) : Promise.resolve(null),
      prisma.careerEmploymentOutcome.findFirst({ where: { studentUserId: userId, createdByUserId: userId }, orderBy: { updatedAt: "desc" }, select: { status: true, companyName: true, positionTitle: true, updatedAt: true } })
    ]);
    return res.json({ ok: true, certificate: cert, outcome });
  } catch (error) {
    return res.status(500).json({ ok: false, message: getErrorMessage(error) });
  }
});

const employmentSurveySchema = z.object({
  status: z.enum(["SEARCHING", "INTERVIEW", "OFFER", "HIRED"]),
  companyName: z.string().trim().max(200).optional(),
  positionTitle: z.string().trim().max(200).optional()
});
app.post("/career-launch/me/employment-status", authenticate, requireCareerEnrollment, async (req, res) => {
  const parsed = employmentSurveySchema.safeParse(req.body);
  if (!parsed.success) return res.status(400).json({ ok: false, message: "invalid request", errors: parsed.error.flatten() });
  const d = parsed.data;
  if (d.status !== "SEARCHING" && !d.companyName?.trim()) {
    return res.status(400).json({ ok: false, message: "회사명을 입력해 주세요." });
  }
  try {
    const userId = req.auth!.userId;
    const enrollment = await prisma.careerEnrollment.findFirst({ where: { studentUserId: userId }, orderBy: { createdAt: "desc" }, select: { cohortId: true } });
    const status = d.status === "SEARCHING" ? "APPLIED" : d.status; // SEARCHING → APPLIED 로 저장
    const companyName = d.status === "SEARCHING" ? "구직 중" : (d.companyName?.trim() || "-");
    const decidedAt = d.status === "HIRED" || d.status === "OFFER" ? new Date() : null;

    // 자기 기록(자기 보고) 1건을 upsert — 있으면 갱신, 없으면 생성.
    const existing = await prisma.careerEmploymentOutcome.findFirst({ where: { studentUserId: userId, createdByUserId: userId }, select: { id: true } });
    if (existing) {
      await prisma.careerEmploymentOutcome.update({
        where: { id: existing.id },
        data: { status, companyName, positionTitle: d.positionTitle?.trim() || null, cohortId: enrollment?.cohortId ?? null, source: "SELF_REPORT", decidedAt }
      });
    } else {
      await prisma.careerEmploymentOutcome.create({
        data: { studentUserId: userId, cohortId: enrollment?.cohortId ?? null, status, companyName, positionTitle: d.positionTitle?.trim() || null, source: "SELF_REPORT", createdByUserId: userId, decidedAt }
      });
    }
    return res.json({ ok: true });
  } catch (error) {
    return res.status(500).json({ ok: false, message: getErrorMessage(error) });
  }
});

// ── Week4 모의면접(유형별: self/job/fit) — 완료한 유형은 progress.interview.practiced 에 누적 ──
const interviewChatSchema = z.object({
  messages: z.array(z.object({ role: z.enum(["bot", "user"]), text: z.string().trim().max(2000) })).max(120).default([]),
  focus: z.enum(["self", "job", "fit"]),
  locale: z.string().max(10).optional()
});
const INTERVIEW_SCHEMA = {
  type: "object",
  additionalProperties: false,
  required: ["reply", "done"],
  properties: { reply: { type: "string" }, done: { type: "boolean" } }
} as const;

app.post(
  "/career-launch/interview-chat",
  authenticate, requireCareerEnrollment,
  rateLimit({ windowMs: 60_000, max: 40, keyPrefix: "career-interview-chat", message: "잠시 후 다시 시도해 주세요." }),
  async (req, res) => {
    const parsed = interviewChatSchema.safeParse(req.body);
    if (!parsed.success) return res.status(400).json({ ok: false, message: "invalid request", errors: parsed.error.flatten() });
    if (!openai) return res.status(503).json({ ok: false, message: "ai unavailable" });
    const { messages, focus, locale } = parsed.data;
    const uid = req.auth!.userId;
    try {
      const [profileSummary, resumeRow, coverRow, progRow] = await Promise.all([
        buildCandidateProfileSummary(uid),
        prisma.careerResumeData.findUnique({ where: { studentUserId: uid } }),
        prisma.careerCoverLetterData.findUnique({ where: { studentUserId: uid } }),
        prisma.careerLaunchProgress.findUnique({ where: { studentUserId: uid } })
      ]);
      const progState = (progRow?.state && typeof progRow.state === "object" ? progRow.state : {}) as Record<string, unknown>;
      const interview = (progState.interview && typeof progState.interview === "object" ? progState.interview : {}) as { practiced?: unknown; results?: unknown };
      const selectedJobs = Array.isArray(progState.selectedJobs) ? (progState.selectedJobs as string[]) : [];
      const practiced = Array.isArray(interview.practiced) ? (interview.practiced as string[]).filter((x) => typeof x === "string") : [];

      const systemPrompt =
        (await getCareerPrompt("interview")) + "\n\n" + CAREER_SCOPE + "\n\n" +
        (await getCareerPrompt(`interview_${focus}`)) + "\n\n" +
        'JSON 한 개 객체로만 응답: { "reply": string, "done": boolean }' +
        aiLangDirective(locale);
      const convo = messages.length
        ? messages.map((m) => `${m.role === "bot" ? "면접관" : "학생"}: ${m.text}`).join("\n")
        : "(아직 대화 없음 — 가볍게 인사하고 이 유형의 첫 질문을 던져줘)";
      const userPrompt =
        (profileSummary ? `[학생 프로필]\n${profileSummary}\n\n` : "") +
        `[선정 직무]\n${selectedJobs.length ? selectedJobs.join(", ") : "(미정)"}\n\n` +
        `[이력서]\n${JSON.stringify(resumeRow?.content ?? {})}\n\n` +
        `[자기소개서]\n${JSON.stringify(coverRow?.content ?? {})}\n\n` +
        `지금까지 대화:\n${convo}`;
      const pj = (await careerChatComplete(systemPrompt, userPrompt, `interview_${focus}`, INTERVIEW_SCHEMA)) as { reply?: unknown; done?: unknown };
      const reply = typeof pj.reply === "string" ? pj.reply.trim() : "";
      const done = pj.done === true;
      if (!reply) return res.status(502).json({ ok: false, message: "ai response empty" });

      // 완료 기준: 그 라운드에서 학생이 3문항 이상 답했거나(참여) AI 가 총평으로 마무리(done)하면 완료.
      const answered = messages.filter((m) => m.role === "user").length;
      const roundDone = done || answered >= 3;
      const newlyPracticed = roundDone && !practiced.includes(focus);
      const prevResults = (interview.results && typeof interview.results === "object" ? interview.results : {}) as Record<string, string>;
      // AI 총평(done)으로 끝나면 그 총평을 최종 피드백용으로 저장.
      if (newlyPracticed || done) {
        const nextInterview: Record<string, unknown> = { ...interview };
        if (newlyPracticed) nextInterview.practiced = [...practiced, focus];
        if (done) nextInterview.results = { ...prevResults, [focus]: reply };
        const mergedState = { ...progState, interview: nextInterview };
        await prisma.careerLaunchProgress.upsert({
          where: { studentUserId: uid },
          create: { studentUserId: uid, state: mergedState as object },
          update: { state: mergedState as object }
        });
      }
      return res.json({ ok: true, reply, done });
    } catch (err) {
      console.error("[career-launch/interview-chat] failed", err);
      return res.status(500).json({ ok: false, message: "failed to continue chat" });
    }
  }
);

// ── 주차 자동 피드백(1~3주차) — 그 주차 결과물을 근거로 AI가 자동 생성, 입력이 바뀌면 갱신 ──
const weekFeedbackSchema = z.object({ week: z.number().int().min(1).max(3) });
const WEEK_FEEDBACK_SCHEMA = {
  type: "object",
  additionalProperties: false,
  required: ["feedback"],
  properties: { feedback: { type: "string" } }
} as const;
const WEEK_FEEDBACK_TITLE: Record<number, string> = { 1: "취업 준비 진단·관심 직무·직무 정보", 2: "대화로 만든 이력서", 3: "대화로 만든 자기소개서" };
// 캐시 무효화용 간단 해시(입력이 바뀌면 값이 달라져 재생성).
function simpleHash(s: string): string {
  let h = 0;
  for (let i = 0; i < s.length; i++) h = (Math.imul(h, 31) + s.charCodeAt(i)) | 0;
  return String(h >>> 0);
}

app.post(
  "/career-launch/week-feedback",
  authenticate, requireCareerEnrollment,
  rateLimit({ windowMs: 60_000, max: 30, keyPrefix: "career-week-feedback", message: "잠시 후 다시 시도해 주세요." }),
  async (req, res) => {
    const parsed = weekFeedbackSchema.safeParse(req.body);
    if (!parsed.success) return res.status(400).json({ ok: false, message: "invalid request" });
    const { week } = parsed.data;
    const uid = req.auth!.userId;
    try {
      const [progRow, resumeRow, coverRow] = await Promise.all([
        prisma.careerLaunchProgress.findUnique({ where: { studentUserId: uid } }),
        week === 2 ? prisma.careerResumeData.findUnique({ where: { studentUserId: uid } }) : Promise.resolve(null),
        week === 3 ? prisma.careerCoverLetterData.findUnique({ where: { studentUserId: uid } }) : Promise.resolve(null)
      ]);
      const progState = (progRow?.state && typeof progRow.state === "object" ? progRow.state : {}) as Record<string, unknown>;

      // 주차별 입력 결과물 + 데이터 유무 판단.
      let input: unknown = {};
      let hasData = false;
      if (week === 1) {
        const diagnosis = progState.diagnosis ?? null;
        const selectedJobs = Array.isArray(progState.selectedJobs) ? progState.selectedJobs : [];
        const materials = Array.isArray(progState.materials) ? progState.materials : [];
        input = { diagnosis, selectedJobs, materials };
        hasData = Boolean(diagnosis) || selectedJobs.length > 0 || materials.length > 0;
      } else if (week === 2) {
        const content = (resumeRow?.content ?? {}) as Record<string, unknown>;
        input = content;
        hasData = hasResumeDataContent(normalizeResumeData(content));
      } else {
        const content = (coverRow?.content ?? {}) as Record<string, unknown>;
        input = content;
        hasData = hasCoverContent(normalizeCoverData(content));
      }
      if (!hasData) return res.json({ ok: true, feedback: null });

      // 캐시 확인 — 입력 해시가 같으면 저장된 피드백 반환(불필요한 재생성·비용 방지).
      const sig = simpleHash(JSON.stringify(input));
      const autoFeedback = (progState.autoFeedback && typeof progState.autoFeedback === "object" ? progState.autoFeedback : {}) as Record<string, { sig?: string; text?: string }>;
      const cached = autoFeedback[String(week)];
      if (cached && cached.sig === sig && typeof cached.text === "string" && cached.text.trim()) {
        return res.json({ ok: true, feedback: cached.text, cached: true });
      }
      if (!openai) return res.status(503).json({ ok: false, message: "ai unavailable" });

      const profileSummary = await buildCandidateProfileSummary(uid);
      const systemPrompt =
        (await getCareerPrompt("auto_feedback")) + "\n\n" +
        'JSON 한 개 객체로만 응답: { "feedback": string }' +
        aiLangDirective("ko");
      const userPrompt =
        (profileSummary ? `[학생 프로필]\n${profileSummary}\n\n` : "") +
        `[${week}주차 결과물: ${WEEK_FEEDBACK_TITLE[week]}]\n${JSON.stringify(input)}`;
      const pj = (await careerChatComplete(systemPrompt, userPrompt, "week_feedback", WEEK_FEEDBACK_SCHEMA)) as { feedback?: unknown };
      const feedback = typeof pj.feedback === "string" ? pj.feedback.trim() : "";
      if (!feedback) return res.status(502).json({ ok: false, message: "ai response empty" });

      const mergedState = { ...progState, autoFeedback: { ...autoFeedback, [String(week)]: { sig, text: feedback } } };
      await prisma.careerLaunchProgress.upsert({
        where: { studentUserId: uid },
        create: { studentUserId: uid, state: mergedState as object },
        update: { state: mergedState as object }
      });
      return res.json({ ok: true, feedback });
    } catch (err) {
      console.error("[career-launch/week-feedback] failed", err);
      return res.status(500).json({ ok: false, message: "failed to generate feedback" });
    }
  }
);

// ── 완주 최종 피드백 — 이력서+자소서+면접 결과를 종합. 입력이 바뀌면 갱신(캐시) ──
const INTERVIEW_TYPE_LABEL: Record<string, string> = { self: "자기소개 면접", job: "직무 면접", fit: "인성·컬처핏 면접" };
// 프롬프트/형식이 바뀌면 올려서 기존 캐시를 한 번 무효화. 이후로는 생성 1회 후 재사용(토큰 절약).
const FINAL_FEEDBACK_VERSION = 2;
app.post(
  "/career-launch/final-feedback",
  authenticate,
  requireCareerEnrollment,
  rateLimit({ windowMs: 60_000, max: 20, keyPrefix: "career-final-feedback", message: "잠시 후 다시 시도해 주세요." }),
  async (req, res) => {
    const uid = req.auth!.userId;
    try {
      const [progRow, resumeRow, coverRow, user] = await Promise.all([
        prisma.careerLaunchProgress.findUnique({ where: { studentUserId: uid } }),
        prisma.careerResumeData.findUnique({ where: { studentUserId: uid } }),
        prisma.careerCoverLetterData.findUnique({ where: { studentUserId: uid } }),
        prisma.user.findUnique({ where: { id: uid }, select: { name: true, realName: true } })
      ]);
      const progState = (progRow?.state && typeof progRow.state === "object" ? progRow.state : {}) as Record<string, unknown>;
      const resumeContent = (resumeRow?.content ?? {}) as Record<string, unknown>;
      const coverContent = (coverRow?.content ?? {}) as Record<string, unknown>;
      // 이력서+자소서가 있어야 최종 피드백(완주 기준). 없으면 null.
      if (!hasResumeDataContent(normalizeResumeData(resumeContent)) || !hasCoverContent(normalizeCoverData(coverContent))) {
        return res.json({ ok: true, feedback: null });
      }

      const interview = (progState.interview && typeof progState.interview === "object" ? progState.interview : {}) as { practiced?: unknown; results?: unknown };
      const practiced = Array.isArray(interview.practiced) ? (interview.practiced as string[]).filter((x) => typeof x === "string") : [];
      const results = (interview.results && typeof interview.results === "object" ? interview.results : {}) as Record<string, string>;
      const currentSig = simpleHash(JSON.stringify({ resume: resumeContent, cover: coverContent, interview: { practiced, results } }));

      // 한 번 생성하면 저장해두고 그대로 재사용(LLM 토큰 절약). force=true(다시 받기)면 재생성.
      // 저장 당시 입력 서명과 현재가 다르면 stale=true 로 알려 프론트에서 '다시 받기' 버튼을 띄운다.
      const force = Boolean(req.body && (req.body as { force?: unknown }).force === true);
      const cached = (progState.finalFeedback && typeof progState.finalFeedback === "object" ? progState.finalFeedback : {}) as { v?: number; sig?: string; text?: string };
      if (!force && cached.v === FINAL_FEEDBACK_VERSION && typeof cached.text === "string" && cached.text.trim()) {
        const stale = typeof cached.sig === "string" && cached.sig !== currentSig;
        return res.json({ ok: true, feedback: cached.text, stale, cached: true });
      }
      if (!openai) return res.status(503).json({ ok: false, message: "ai unavailable" });

      const studentName = (user?.realName?.trim() || user?.name?.trim() || ((resumeContent.basic as { name?: string } | undefined)?.name ?? "").trim() || "").trim();
      const profileSummary = await buildCandidateProfileSummary(uid);
      const interviewText = practiced.length
        ? practiced.map((t) => `- ${INTERVIEW_TYPE_LABEL[t] ?? t}${results[t] ? `: ${results[t]}` : " (연습 완료)"}`).join("\n")
        : "(아직 면접 연습 없음)";
      const systemPrompt =
        (await getCareerPrompt("final_feedback")) + "\n\n" +
        'JSON 한 개 객체로만 응답: { "feedback": string }' +
        aiLangDirective("ko");
      const userPrompt =
        (studentName ? `[학생 이름] ${studentName} (피드백에서 이 이름으로 '${studentName}님'처럼 불러줘)\n\n` : "") +
        (profileSummary ? `[학생 프로필]\n${profileSummary}\n\n` : "") +
        `[이력서]\n${JSON.stringify(resumeContent)}\n\n` +
        `[자기소개서]\n${JSON.stringify(coverContent)}\n\n` +
        `[모의면접 결과]\n${interviewText}`;
      const pj = (await careerChatComplete(systemPrompt, userPrompt, "final_feedback", WEEK_FEEDBACK_SCHEMA)) as { feedback?: unknown };
      const feedback = typeof pj.feedback === "string" ? pj.feedback.trim() : "";
      if (!feedback) return res.status(502).json({ ok: false, message: "ai response empty" });

      const mergedState = { ...progState, finalFeedback: { v: FINAL_FEEDBACK_VERSION, sig: currentSig, text: feedback } };
      await prisma.careerLaunchProgress.upsert({
        where: { studentUserId: uid },
        create: { studentUserId: uid, state: mergedState as object },
        update: { state: mergedState as object }
      });
      return res.json({ ok: true, feedback, stale: false });
    } catch (err) {
      console.error("[career-launch/final-feedback] failed", err);
      return res.status(500).json({ ok: false, message: "failed to generate feedback" });
    }
  }
);

// ── Career Launch 운영자(어드민) — 프롬프트 편집 ──
// GET /career-launch/ops/prompts — 스텝별 프롬프트(기본값 + 편집분) 목록.
app.get("/career-launch/ops/prompts", authenticate, requireRoles([MemberRole.OPERATOR]), async (_req, res) => {
  try {
    const rows = await prisma.appSetting.findMany({ where: { key: { startsWith: "career_prompt_" } } });
    const overrides = new Map(rows.map((r) => [r.key, r.value] as const));
    const items = Object.entries(CAREER_PROMPTS).map(([key, v]) => {
      const override = overrides.get(`career_prompt_${key}`);
      return { key, label: v.label, week: v.week, step: v.step, default: v.default, value: override ?? v.default, isOverridden: typeof override === "string" };
    });
    return res.json({ ok: true, items });
  } catch (error) {
    return res.status(500).json({ ok: false, message: getErrorMessage(error) });
  }
});

// PUT /career-launch/ops/prompts/:key — 프롬프트 편집분 저장.
const careerPromptPutSchema = z.object({ value: z.string().trim().min(1).max(20000) });
app.put("/career-launch/ops/prompts/:key", authenticate, requireRoles([MemberRole.OPERATOR]), async (req, res) => {
  const key = typeof req.params.key === "string" ? req.params.key : "";
  if (!CAREER_PROMPTS[key]) return res.status(404).json({ ok: false, message: "unknown prompt key" });
  const parsed = careerPromptPutSchema.safeParse(req.body);
  if (!parsed.success) return res.status(400).json({ ok: false, message: "invalid request", errors: parsed.error.flatten() });
  try {
    await prisma.appSetting.upsert({
      where: { key: `career_prompt_${key}` },
      update: { value: parsed.data.value, description: `Career Launch 프롬프트: ${CAREER_PROMPTS[key].label}` },
      create: { key: `career_prompt_${key}`, value: parsed.data.value, description: `Career Launch 프롬프트: ${CAREER_PROMPTS[key].label}` }
    });
    return res.json({ ok: true });
  } catch (error) {
    return res.status(500).json({ ok: false, message: getErrorMessage(error) });
  }
});

// DELETE /career-launch/ops/prompts/:key — 편집분 삭제(기본값으로 복원).
app.delete("/career-launch/ops/prompts/:key", authenticate, requireRoles([MemberRole.OPERATOR]), async (req, res) => {
  const key = typeof req.params.key === "string" ? req.params.key : "";
  if (!CAREER_PROMPTS[key]) return res.status(404).json({ ok: false, message: "unknown prompt key" });
  try {
    await prisma.appSetting.deleteMany({ where: { key: `career_prompt_${key}` } });
    return res.json({ ok: true, default: CAREER_PROMPTS[key].default });
  } catch (error) {
    return res.status(500).json({ ok: false, message: getErrorMessage(error) });
  }
});

// ── Career Launch 운영자(어드민) — 학생 진행 현황 ──
// GET /career-launch/ops/students — Career Launch 를 이용한(진행/이력서 데이터가 있는) 학생 목록 + 요약.
app.get("/career-launch/ops/students", authenticate, requireRoles([MemberRole.OPERATOR]), async (req, res) => {
  const cohortFilter = typeof req.query.cohortId === "string" ? req.query.cohortId : "";
  try {
    const [enrollRows, progressRows, resumeRows, coverRows] = await Promise.all([
      prisma.careerEnrollment.findMany({
        include: {
          cohort: { select: { id: true, university: true, name: true } },
          student: { select: { id: true, name: true, realName: true, email: true, phoneNumber: true } }
        },
        orderBy: { createdAt: "asc" }
      }),
      prisma.careerLaunchProgress.findMany({ include: { student: { select: { id: true, name: true, realName: true, email: true, phoneNumber: true } } } }),
      prisma.careerResumeData.findMany({ select: { studentUserId: true, content: true, updatedAt: true } }),
      prisma.careerCoverLetterData.findMany({ select: { studentUserId: true, content: true, updatedAt: true } })
    ]);

    // 학생 → 소속 기수(첫 등록 기준).
    const cohortByUser = new Map<string, { id: string; university: string; name: string }>();
    for (const e of enrollRows) if (e.student && !cohortByUser.has(e.studentUserId)) cohortByUser.set(e.studentUserId, e.cohort);

    // 대상 학생 = 등록 학생 + 데이터(progress/resume/cover)가 있는 학생.
    const byUser = new Map<string, { id: string; name: string | null; realName: string | null; email: string; phoneNumber: string | null }>();
    for (const e of enrollRows) if (e.student) byUser.set(e.student.id, e.student);
    for (const p of progressRows) if (p.student) byUser.set(p.student.id, p.student);
    const dataIds = [...new Set([...resumeRows.map((r) => r.studentUserId), ...coverRows.map((c) => c.studentUserId)])];
    const missing = dataIds.filter((id) => !byUser.has(id));
    if (missing.length) {
      const users = await prisma.user.findMany({ where: { id: { in: missing } }, select: { id: true, name: true, realName: true, email: true, phoneNumber: true } });
      for (const u of users) byUser.set(u.id, u);
    }

    const progMap = new Map(progressRows.map((p) => [p.studentUserId, p] as const));
    const resumeMap = new Map(resumeRows.map((r) => [r.studentUserId, r] as const));
    const coverMap = new Map(coverRows.map((c) => [c.studentUserId, c] as const));
    const arrLen = (v: unknown) => (Array.isArray(v) ? v.length : 0);

    let items = Array.from(byUser.values()).map((u) => {
      const st = (progMap.get(u.id)?.state ?? {}) as Record<string, unknown>;
      const diag = (st.diagnosis ?? null) as { percent?: number } | null;
      const interview = (st.interview && typeof st.interview === "object" ? st.interview : {}) as { practiced?: unknown };
      const resume = resumeMap.get(u.id);
      const rc = (resume?.content ?? {}) as Record<string, unknown>;
      const cover = coverMap.get(u.id);
      const cc = (cover?.content ?? {}) as Record<string, unknown>;
      const coverItems = Array.isArray(cc.items) ? (cc.items as { answer?: string }[]).filter((x) => (x.answer ?? "").trim()) : [];
      return {
        userId: u.id,
        // 실명 우선 — name 은 SNS 닉네임일 수 있어 연락·공식 문서에 부적합하다.
        name: u.realName ?? u.name ?? null,
        realName: u.realName ?? null,
        email: u.email,
        phone: u.phoneNumber ?? null,
        cohort: cohortByUser.get(u.id) ?? null,
        diagnosisPercent: typeof diag?.percent === "number" ? diag.percent : null,
        selectedJobs: arrLen(st.selectedJobs),
        materials: arrLen(st.materials),
        doneSteps: arrLen(st.doneSteps),
        hasResume: arrLen(rc.educations) + arrLen(rc.experiences) + arrLen(rc.skills) > 0 || Boolean((rc.basic as { name?: string } | undefined)?.name),
        coverItems: coverItems.length,
        interviewPracticed: arrLen(interview.practiced),
        updatedAt: progMap.get(u.id)?.updatedAt ?? resume?.updatedAt ?? cover?.updatedAt ?? null
      };
    });
    if (cohortFilter) items = items.filter((it) => it.cohort?.id === cohortFilter);
    items.sort((a, b) => String(b.updatedAt ?? "").localeCompare(String(a.updatedAt ?? "")));
    return res.json({ ok: true, items });
  } catch (error) {
    return res.status(500).json({ ok: false, message: getErrorMessage(error) });
  }
});

// ── Career Launch 기수(Cohort)·등록 관리 ──
function genCareerInviteCode(): string {
  const chars = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789"; // 헷갈리는 글자(0/O/1/I) 제외
  let c = "";
  for (let i = 0; i < 6; i++) c += chars[Math.floor(Math.random() * chars.length)];
  return c;
}
async function genUniqueInviteCode(): Promise<string> {
  for (let i = 0; i < 8; i++) {
    const code = genCareerInviteCode();
    const exists = await prisma.careerCohort.findUnique({ where: { inviteCode: code }, select: { id: true } });
    if (!exists) return code;
  }
  return genCareerInviteCode() + genCareerInviteCode();
}

// 운영자: 기수 목록(+등록 인원)
app.get("/career-launch/ops/cohorts", authenticate, requireRoles([MemberRole.OPERATOR]), async (_req, res) => {
  try {
    const rows = await prisma.careerCohort.findMany({ orderBy: { createdAt: "desc" }, include: { _count: { select: { enrollments: true } } } });
    const items = rows.map((c) => ({ id: c.id, university: c.university, name: c.name, inviteCode: c.inviteCode, status: c.status, startsAt: c.startsAt, endsAt: c.endsAt, enrolledCount: c._count.enrollments, createdAt: c.createdAt }));
    return res.json({ ok: true, items });
  } catch (error) {
    return res.status(500).json({ ok: false, message: getErrorMessage(error) });
  }
});

// 운영자: 기수 생성(초대코드 자동 발급)
const cohortCreateSchema = z.object({
  university: z.string().trim().min(1).max(120),
  name: z.string().trim().min(1).max(80),
  startsAt: z.string().datetime().optional(),
  endsAt: z.string().datetime().optional()
});
app.post("/career-launch/ops/cohorts", authenticate, requireRoles([MemberRole.OPERATOR]), async (req, res) => {
  const parsed = cohortCreateSchema.safeParse(req.body);
  if (!parsed.success) return res.status(400).json({ ok: false, message: "invalid request", errors: parsed.error.flatten() });
  try {
    const inviteCode = await genUniqueInviteCode();
    const c = await prisma.careerCohort.create({
      data: {
        university: parsed.data.university,
        name: parsed.data.name,
        inviteCode,
        startsAt: parsed.data.startsAt ? new Date(parsed.data.startsAt) : null,
        endsAt: parsed.data.endsAt ? new Date(parsed.data.endsAt) : null
      }
    });
    return res.status(201).json({ ok: true, item: c });
  } catch (error) {
    return res.status(500).json({ ok: false, message: getErrorMessage(error) });
  }
});

// 운영자: 기수 수정(대학·이름·상태·기간)
const cohortPatchSchema = z.object({
  university: z.string().trim().min(1).max(120).optional(),
  name: z.string().trim().min(1).max(80).optional(),
  status: z.enum(["active", "ended"]).optional(),
  startsAt: z.string().datetime().nullable().optional(),
  endsAt: z.string().datetime().nullable().optional()
});
app.patch("/career-launch/ops/cohorts/:id", authenticate, requireRoles([MemberRole.OPERATOR]), async (req, res) => {
  const parsed = cohortPatchSchema.safeParse(req.body);
  if (!parsed.success) return res.status(400).json({ ok: false, message: "invalid request" });
  const id = String(req.params.id ?? "");
  try {
    const data: Record<string, unknown> = {};
    if (parsed.data.university !== undefined) data.university = parsed.data.university;
    if (parsed.data.name !== undefined) data.name = parsed.data.name;
    if (parsed.data.status !== undefined) data.status = parsed.data.status;
    if (parsed.data.startsAt !== undefined) data.startsAt = parsed.data.startsAt ? new Date(parsed.data.startsAt) : null;
    if (parsed.data.endsAt !== undefined) data.endsAt = parsed.data.endsAt ? new Date(parsed.data.endsAt) : null;
    const c = await prisma.careerCohort.update({ where: { id }, data });
    return res.json({ ok: true, item: c });
  } catch (error) {
    return res.status(500).json({ ok: false, message: getErrorMessage(error) });
  }
});

