// 운영자: 기수 상세(+등록 학생 목록)
app.get("/career-launch/ops/cohorts/:id", authenticate, requireRoles([MemberRole.OPERATOR]), async (req, res) => {
  const id = String(req.params.id ?? "");
  try {
    const c = await prisma.careerCohort.findUnique({
      where: { id },
      include: {
        enrollments: { include: { student: { select: { id: true, name: true, realName: true, email: true } } }, orderBy: { createdAt: "desc" } },
        seminars: { orderBy: { week: "asc" } },
        weeks: { orderBy: { week: "asc" } }
      }
    });
    if (!c) return res.status(404).json({ ok: false, message: "cohort not found" });
    // 학생별 진행 현황 — 리포트와 동일 원본(진단 state·이력서/자소서 content)에서 계산.
    const ids = c.enrollments.map((e) => e.studentUserId);
    const [progressRows, resumeRows, coverRows] = await Promise.all([
      prisma.careerLaunchProgress.findMany({ where: { studentUserId: { in: ids } } }),
      prisma.careerResumeData.findMany({ where: { studentUserId: { in: ids } }, select: { studentUserId: true, content: true } }),
      prisma.careerCoverLetterData.findMany({ where: { studentUserId: { in: ids } }, select: { studentUserId: true, content: true } })
    ]);
    const progByUser = new Map(progressRows.map((p) => [p.studentUserId, p] as const));
    const resumeByUser = new Map(resumeRows.map((r) => [r.studentUserId, r] as const));
    const coverByUser = new Map(coverRows.map((cc) => [cc.studentUserId, cc] as const));
    const pctOfVal = (v: unknown) => {
      const p = (v as { percent?: unknown } | null)?.percent;
      return typeof p === "number" ? p : null;
    };
    const buildProgress = (userId: string) => {
      const st = (progByUser.get(userId)?.state ?? {}) as Record<string, unknown>;
      const interview = (st.interview && typeof st.interview === "object" ? st.interview : {}) as { practiced?: unknown };
      const practiced = Array.isArray(interview.practiced) ? (interview.practiced as string[]) : [];
      const rc = (resumeByUser.get(userId)?.content ?? {}) as Record<string, unknown>;
      const cc = (coverByUser.get(userId)?.content ?? {}) as Record<string, unknown>;
      const hasResume =
        (Array.isArray(rc.educations) && rc.educations.length > 0) ||
        (Array.isArray(rc.experiences) && rc.experiences.length > 0) ||
        (Array.isArray(rc.skills) && rc.skills.length > 0) ||
        Boolean((rc.basic as { name?: string } | undefined)?.name);
      const coverItems = Array.isArray(cc.items) ? (cc.items as { answer?: string }[]).filter((x) => (x.answer ?? "").trim()).length : 0;
      const before = pctOfVal(st.diagnosisInitial) ?? pctOfVal(st.diagnosis);
      const after = pctOfVal(st.diagnosisFinal);
      const selectedJobs = Array.isArray(st.selectedJobs) ? (st.selectedJobs as unknown[]).length : 0;
      const doneSteps = Array.isArray(st.doneSteps) ? (st.doneSteps as unknown[]).filter((x): x is string => typeof x === "string") : [];
      const weeksCompleted = [1, 2, 3, 4].filter((w) => doneSteps.includes(`w${w}s4`)).length;
      const interviewPracticed = practiced.length;
      return {
        diagnosed: before !== null,
        diagnosisBefore: before,
        diagnosisAfter: after,
        selectedJobs,
        hasResume,
        hasCover: coverItems > 0,
        interviewPracticed,
        doneStepsCount: doneSteps.length,
        weeksCompleted,
        completed: interviewPracticed >= 3 && hasResume && coverItems > 0
      };
    };
    const students = c.enrollments.map((e) => ({
      studentUserId: e.studentUserId,
      // 실명 우선 — name 은 SNS 닉네임(예: 'Genetory')일 수 있어 공식 문서·연락에 부적합하다.
        name: e.student?.realName ?? e.student?.name ?? null,
      email: e.student?.email ?? "",
      enrolledAt: e.createdAt,
      progress: buildProgress(e.studentUserId)
    }));
    const seminars = c.seminars.map((s) => ({ week: s.week, title: s.title, startsAt: s.startsAt, location: s.location, online: s.online, url: s.url }));
    // 주차 오픈 일정 — 1~4주차 모두 표시(미설정 주차는 opensAt null·forceOpen false 로 채움).
    const weekMap = new Map(c.weeks.map((w) => [w.week, w] as const));
    const weekSchedule = [1, 2, 3, 4].map((w) => ({
      week: w,
      opensAt: weekMap.get(w)?.opensAt ?? null,
      forceOpen: weekMap.get(w)?.forceOpen ?? false
    }));
    return res.json({ ok: true, item: { id: c.id, university: c.university, name: c.name, inviteCode: c.inviteCode, status: c.status, startsAt: c.startsAt, endsAt: c.endsAt, students, seminars, weekSchedule } });
  } catch (error) {
    return res.status(500).json({ ok: false, message: getErrorMessage(error) });
  }
});

// 운영자: 기수 주차 오픈 일정 설정 — 오픈일(opensAt) 지정 또는 강제 오픈(forceOpen) 토글.
const cohortWeekSchema = z.object({
  opensAt: z.string().min(1).nullable().optional(),
  forceOpen: z.boolean().optional()
});
app.put("/career-launch/ops/cohorts/:cohortId/weeks/:week", authenticate, requireRoles([MemberRole.OPERATOR]), async (req, res) => {
  const cohortId = String(req.params.cohortId ?? "");
  const week = Number(req.params.week);
  if (!cohortId || !Number.isInteger(week) || week < 1 || week > 4) return res.status(400).json({ ok: false, message: "invalid params" });
  const parsed = cohortWeekSchema.safeParse(req.body);
  if (!parsed.success) return res.status(400).json({ ok: false, message: "invalid request", errors: parsed.error.flatten() });
  try {
    const opensAt = parsed.data.opensAt === undefined ? undefined : parsed.data.opensAt === null ? null : new Date(parsed.data.opensAt);
    if (opensAt instanceof Date && Number.isNaN(opensAt.getTime())) return res.status(400).json({ ok: false, message: "invalid opensAt" });
    const row = await prisma.careerCohortWeek.upsert({
      where: { cohortId_week: { cohortId, week } },
      create: { cohortId, week, opensAt: opensAt ?? null, forceOpen: parsed.data.forceOpen ?? false },
      update: {
        ...(opensAt !== undefined ? { opensAt } : {}),
        ...(parsed.data.forceOpen !== undefined ? { forceOpen: parsed.data.forceOpen } : {})
      }
    });
    return res.json({ ok: true, week: { week: row.week, opensAt: row.opensAt, forceOpen: row.forceOpen } });
  } catch (error) {
    return res.status(500).json({ ok: false, message: getErrorMessage(error) });
  }
});

// 운영자: 기수 세미나 일정 입력(주차별 1건 upsert) / 삭제
const seminarSchema = z.object({
  title: z.string().max(200).nullable().optional(),
  startsAt: z.string().min(1),
  location: z.string().max(300).nullable().optional(),
  online: z.boolean().optional(),
  url: z.string().max(500).nullable().optional()
});
app.put("/career-launch/ops/cohorts/:cohortId/seminars/:week", authenticate, requireRoles([MemberRole.OPERATOR]), async (req, res) => {
  const cohortId = String(req.params.cohortId ?? "");
  const week = Number(req.params.week);
  if (!cohortId || !Number.isInteger(week) || week < 1 || week > 4) return res.status(400).json({ ok: false, message: "invalid params" });
  const parsed = seminarSchema.safeParse(req.body);
  if (!parsed.success) return res.status(400).json({ ok: false, message: "invalid request", errors: parsed.error.flatten() });
  try {
    const d = parsed.data;
    const startsAt = new Date(d.startsAt);
    if (Number.isNaN(startsAt.getTime())) return res.status(400).json({ ok: false, message: "invalid startsAt" });
    const seminar = await prisma.careerSeminar.upsert({
      where: { cohortId_week: { cohortId, week } },
      create: { cohortId, week, title: d.title ?? null, startsAt, location: d.location ?? null, online: d.online ?? false, url: d.url ?? null },
      update: { title: d.title ?? null, startsAt, location: d.location ?? null, online: d.online ?? false, url: d.url ?? null }
    });
    return res.json({ ok: true, seminar });
  } catch (error) {
    return res.status(500).json({ ok: false, message: getErrorMessage(error) });
  }
});
app.delete("/career-launch/ops/cohorts/:cohortId/seminars/:week", authenticate, requireRoles([MemberRole.OPERATOR]), async (req, res) => {
  const cohortId = String(req.params.cohortId ?? "");
  const week = Number(req.params.week);
  if (!cohortId || !Number.isInteger(week)) return res.status(400).json({ ok: false, message: "invalid params" });
  try {
    await prisma.careerSeminar.deleteMany({ where: { cohortId, week } });
    return res.json({ ok: true });
  } catch (error) {
    return res.status(500).json({ ok: false, message: getErrorMessage(error) });
  }
});

// 학생: 내 기수의 세미나 일정(주차별)
